.skh-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #fff);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #000);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.skh-root,.skh-root *,.skh-root *::before,.skh-root *::after{box-sizing:border-box}
.skh-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.skh-root img{display:block;border:0;max-width:none}
.skh-root .n64_3419{align-content:stretch;display:flex;align-items:center;justify-content:space-between;position:relative;flex-shrink:0;width:100%}
.skh-root .n64_3420{align-content:stretch;display:flex;align-items:center;justify-content:center;position:relative;flex-shrink:0}
.skh-root .n64_3421{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:19px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-point, #3a3679);font-size:16px;white-space:nowrap;width:42px}
.skh-root .n64_3422{align-content:stretch;display:flex;gap:12px;align-items:baseline;justify-content:flex-end;position:relative;flex-shrink:0}
.skh-root .n64_3423{align-content:stretch;display:flex;align-items:center;justify-content:flex-end;position:relative;flex-shrink:0}
.skh-root .n64_3424{word-break:break-word;font-family:"Tomorrow","Pretendard",system-ui,sans-serif;font-weight:500;line-height:29px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #313131);font-size:24px;text-align:right;white-space:nowrap;width:71px}
.skh-root .n64_3425{align-content:stretch;display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;flex-shrink:0}
.skh-root .n64_3426{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:14px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #888);font-size:12px;white-space:nowrap;width:16px}
.skh-root[data-theme="dark"] .n64_3421{color:var(--wa-point, #c9c7ff)}
.skh-root[data-theme="dark"] .n64_3424{color:var(--wa-text, #eceffa)}
.skh-root[data-theme="dark"] .n64_3426{color:var(--wa-text-sub, #9199b1)}
.skh-root[data-theme="dark"] [id="skh-Needle"] svg [id$="-Vector"] path{fill:var(--wa-point, #242a44)}
.skh-root[data-theme="dark"] [id="skh-Needle"] svg [id$="-Vector_2"] path{fill:var(--wa-point, #dfe3f2)}
.skh-root[data-theme="dark"] [id="skh-Needle"] svg [id$="-Vector_3"]{stroke:var(--wa-point, #dfe3f2)}
.skh-root[data-theme="dark"] [id="skh-Needle"] img{filter:invert(.86) hue-rotate(180deg)}
.skh-root[data-theme="dark"] [id="skh-Radio"] svg rect:first-of-type{fill:var(--wa-point, #2a3050)}
